mapper.sql:
WHERE owner_id = #{ownerId}

    AND (
        LOWER(name) LIKE #{keywordPattern}
        OR LOWER(COALESCE(display_name, '')) LIKE #{keywordPattern}
        OR LOWER(COALESCE(semantic_role, '')) LIKE #{keywordPattern}
    )


    AND status = #{status}


    AND semantic_role = #{semanticRole}

mapper.insert:
