mapper.select:
SELECT 
FROM field_definitions
WHERE id = #{id,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  AND owner_id = #{ownerId}

mapper.delete:
DELETE FROM field_definitions
WHERE id = #{id,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  AND owner_id = #{ownerId}

mapper.select:
SELECT COUNT(*)
FROM field_definitions
WHERE owner_id = #{ownerId}
  AND LOWER(name) = LOWER(#{name})

    AND id <> #{excludeId,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
